    font-family: var(--font-display);
    font-weight: 900;
    font-size: clamp(3rem, 6vw, 5rem);
    line-height: 0.9;
    margin-bottom: 1rem;
    color: #fff;
    text-transform: uppercase;
    letter-spacing: -0.03em;
  }

